package com.digitalhealth.service;
import com.digitalhealth.dto.AuthDTO; import com.digitalhealth.model.*; import com.digitalhealth.repository.*; import com.digitalhealth.security.TokenService; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.web.server.ResponseStatusException;
@Service public class AuthService { private final UserAccountRepository users; private final WorkerRepository workers; private final PasswordEncoder passwords; private final TokenService tokens; private final EmailOtpService otp; public AuthService(UserAccountRepository u,WorkerRepository w,PasswordEncoder p,TokenService t,EmailOtpService o){users=u;workers=w;passwords=p;tokens=t;otp=o;} public AuthDTO.Response register(AuthDTO.Register d){if(users.findByUsernameIgnoreCase(d.username).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Username is already registered");if(users.findByEmailIgnoreCase(d.email.trim()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");if(d.role==Role.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Administrator accounts cannot be self-registered");UserAccount a=new UserAccount();a.setUsername(d.username.trim());a.setEmail(d.email.trim().toLowerCase());a.setPasswordHash(passwords.encode(d.password));a.setRole(d.role);if(d.role==Role.WORKER){if(d.workerId==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A worker ID is required for a worker account");var w=workers.findById(d.workerId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Worker not found"));if(users.findByWorkerId(w.getId()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"This worker already has an account");a.setWorker(w);}return response(users.save(a));} public AuthDTO.OtpResponse login(AuthDTO.Login d){var a=users.findByUsernameIgnoreCase(d.username).filter(UserAccount::isEnabled).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password"));if(!passwords.matches(d.password,a.getPasswordHash()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid username or password");if(a.getEmail()==null||a.getEmail().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This account has no email address. Create a new account with an email address.");otp.send(a.getUsername(),a.getEmail());return new AuthDTO.OtpResponse("A 6-digit verification code was sent to your email address.",a.getUsername());} public AuthDTO.Response verifyOtp(AuthDTO.VerifyOtp d){otp.verify(d.username,d.code);var a=users.findByUsernameIgnoreCase(d.username).filter(UserAccount::isEnabled).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account is unavailable"));return response(a);} private AuthDTO.Response response(UserAccount a){return new AuthDTO.Response(tokens.issue(a),a.getUsername(),a.getRole(),a.getWorker()==null?null:a.getWorker().getId());} }
